<template>
  <div class="container-fluid">
    <div class="box">
      <iframe 
        v-if="pdfCategoryUrl"
        :src="`${pdfCategoryUrl}#toolbar=1`"
        width="100%" 
        height="100%" 
        title="Product Report"
        style="border: none;"
      />
      <p v-else-if="message">{{ message }}</p>
      <p v-else>Loading report...</p>
    </div>
  </div>
</template>

<script setup lang="ts">
    import axios from 'axios';
    import { ref, onMounted, onUnmounted} from 'vue';

    const message = ref('');
    const pdfCategoryUrl = ref<string | null>(null);

    const api = axios.create({
        baseURL: "http://127.0.0.1:8000",
        headers: {'Accept': 'application/json',
                'Content-Type': 'application/json'}
    })

    async function getCategory() {
        try {
            const res = await api.get('/api/productbycategory', {
                responseType: 'blob'
            });

            const blob = new Blob([res.data], { type: 'application/pdf' });
            pdfCategoryUrl.value = URL.createObjectURL(blob);

        } catch (error: any) {
            console.log(error);
            message.value = "Failed to load PDF: " + error.message;
        }
    }

    onMounted(() => {
        getCategory()
    });

    onUnmounted(() => {
        if (pdfCategoryUrl.value) {
            URL.revokeObjectURL(pdfCategoryUrl.value);
        }
    });

</script>

<style scoped>
    .box {
    height: 100vh;
    width: 100%;
    }
</style>

